<template><el-dialog v-model="visible" title="工资修改记录" width="900px"><el-table :data="logs" v-loading="loading"><el-table-column prop="createTime" label="修改时间" width="170"/><el-table-column prop="changeByName" label="修改人" width="110"/><el-table-column prop="changeReason" label="修改原因" min-width="180"/><el-table-column type="expand"><template #default="scope"><el-descriptions :column="1" border><el-descriptions-item label="差异"><pre>{{ formatDiff(scope.row.diffData) }}</pre></el-descriptions-item><el-descriptions-item label="修改前"><pre>{{ formatJson(scope.row.beforeData) }}</pre></el-descriptions-item><el-descriptions-item label="修改后"><pre>{{ formatJson(scope.row.afterData) }}</pre></el-descriptions-item></el-descriptions></template></el-table-column></el-table><el-empty v-if="!loading&&!logs.length" description="暂无修改记录" /></el-dialog></template>
<script setup lang="ts">import { ref } from "vue";import { getSalaryLogList } from "@/api/modules/hr";import type { SalaryChangeLog } from "@/api/interface/hr";import { fieldLabels } from "../fields";const visible=ref(false),loading=ref(false),logs=ref<SalaryChangeLog[]>([]);const parse=(v?:string)=>{try{return JSON.parse(v||"");}catch{return v||"";}};const formatJson=(v?:string)=>{const x=parse(v);return typeof x==="string"?x:JSON.stringify(x,null,2);};const formatDiff=(v?:string)=>{const x=parse(v);if(!x||typeof x!=="object")return String(x||"");return Object.entries(x).map(([key,value]:any)=>`${fieldLabels[key]||key}：${value?.before??value?.old??""} → ${value?.after??value?.new??""}`).join("\n");};const open=async(salaryId:number)=>{visible.value=true;loading.value=true;try{logs.value=(await getSalaryLogList(salaryId)).data;}finally{loading.value=false;}};defineExpose({open});</script><style scoped>pre{margin:0;white-space:pre-wrap;word-break:break-all}</style>
